import requests

# Put your NEW access token here (from the refresh script)
access_token = "v^1.1#i^1#f^0#I^3#r^0#p^3#t^"

# Test 1: Get fulfillment policy
url = "https://api.sandbox.ebay.com/sell/account/v1/fulfillment_policy"
headers = {"Authorization": f"Bearer {access_token}"}
